'use strict';

const assert = require('node:assert/strict');
const { createHash } = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const [phase, rootArgument] = process.argv.slice(2);
if (!['before', 'after'].includes(phase) || !rootArgument) {
  console.error('Usage: node compare-title-validators.cjs <before|after> <repository-root>');
  process.exit(2);
}

const repoRoot = fs.realpathSync(rootArgument);
const contractDirectory = path.join(
  repoRoot,
  'aidlc/spaces/default/intents/260914-catchu-october-mvp/inception/contract-design',
);
const fixtureFile = path.join(
  repoRoot,
  'worker/fixtures/m1-synthetic/results/succeeded-one-candidate.json',
);
const contextFile = path.join(repoRoot, 'worker/fixtures/m1-synthetic/context.sample.json');
const { WorkerMessageValidator } = require(
  path.join(repoRoot, 'api/dist/analysis-receiver/worker-message.validator'),
);
const { checkMessage, fillTemplate } = require(
  path.join(repoRoot, 'api/test/helpers/worker-messages.cjs'),
);
const values = {
  ...JSON.parse(fs.readFileSync(contextFile, 'utf8')).values,
  caseId: 'succeeded-one-candidate',
};
const filled = fillTemplate(JSON.parse(fs.readFileSync(fixtureFile, 'utf8')), values);
assert.doesNotMatch(JSON.stringify(filled), /\{\{/);
assert.equal(filled.sourceMode, 'MOCK');

// uv runs from worker/ so its locked project environment and app imports are used.
// The worker independently fills the same original synthetic template.
const pythonSource = String.raw`
import copy
import json
from pathlib import Path

from app.contract.worker_messages import check_message, fill_template

fixture_dir = Path("fixtures/m1-synthetic")
template = json.loads((fixture_dir / "results/succeeded-one-candidate.json").read_text(encoding="utf-8"))
context = json.loads((fixture_dir / "context.sample.json").read_text(encoding="utf-8"))["values"]
filled = fill_template(template, {**context, "caseId": "succeeded-one-candidate"})
assert "{{" not in json.dumps(filled, ensure_ascii=False)
assert filled["sourceMode"] == "MOCK"

def check(message):
    result = check_message("Result", message)
    return {
        "verdict": str(result.verdict),
        "unidentifiedFields": list(result.unidentified_fields),
        "errors": [{"path": error.path, "keyword": error.keyword} for error in result.errors],
    }

cases = {}
for name in ("null", "empty", "missing"):
    message = copy.deepcopy(filled)
    if name == "missing":
        del message["candidates"][0]["title"]
    else:
        message["candidates"][0]["title"] = None if name == "null" else ""
    cases[name] = check(message)

print(json.dumps({"filled": filled, "baseline": check(filled), "cases": cases}, ensure_ascii=False))
`;
const workerProcess = spawnSync('uv', ['run', '--locked', 'python', '-c', pythonSource], {
  cwd: path.join(repoRoot, 'worker'),
  encoding: 'utf8',
  maxBuffer: 1024 * 1024,
});
if (workerProcess.error) throw workerProcess.error;
if (workerProcess.status !== 0) {
  process.stderr.write(workerProcess.stderr || 'Worker comparison process failed.\n');
  process.exit(workerProcess.status ?? 1);
}
if (workerProcess.stderr) process.stderr.write(workerProcess.stderr);
const worker = JSON.parse(workerProcess.stdout);
assert.deepEqual(worker.filled, filled, 'fillTemplate and fill_template produced different inputs');

const runtime = new WorkerMessageValidator(contractDirectory);
const baseline = {
  apiRuntime: runtime.result(structuredClone(filled)),
  apiHelper: checkMessage('Result', structuredClone(filled)),
  workerHelper: worker.baseline,
};
baseline.passed = baseline.apiRuntime === true
  && baseline.apiHelper.verdict === 'VALID'
  && baseline.workerHelper.verdict === 'VALID';

const cases = ['null', 'empty', 'missing'].map((name) => {
  const message = structuredClone(filled);
  if (name === 'missing') delete message.candidates[0].title;
  else message.candidates[0].title = name === 'null' ? null : '';
  const expectedRuntime = phase === 'after' && name === 'null';
  const expectedVerdict = expectedRuntime ? 'VALID' : 'SCHEMA_INVALID';
  const row = {
    case: name,
    apiRuntime: runtime.result(message),
    apiHelper: checkMessage('Result', message),
    workerHelper: worker.cases[name],
    expected: { apiRuntime: expectedRuntime, helperVerdict: expectedVerdict },
  };
  row.passed = typeof row.apiRuntime === 'boolean'
    && row.apiRuntime === expectedRuntime
    && row.apiHelper.verdict === expectedVerdict
    && row.workerHelper.verdict === expectedVerdict
    && row.apiHelper.unidentifiedFields.length === 0
    && row.workerHelper.unidentifiedFields.length === 0;
  return row;
});

const summary = {
  phase,
  repositoryRoot: repoRoot,
  contractDirectory,
  fixtureFile,
  fixtureSha256: createHash('sha256').update(fs.readFileSync(fixtureFile)).digest('hex'),
  contractSha256: Object.fromEntries(['worker-messages.yaml', 'common.yaml'].map((name) => [
    name,
    createHash('sha256').update(fs.readFileSync(path.join(contractDirectory, name))).digest('hex'),
  ])),
  syntheticInput: { contextFile, sourceMode: filled.sourceMode, fillingFunctionsAgree: true },
  baseline,
  cases,
  passed: baseline.passed && cases.every((row) => row.passed),
};
console.log(JSON.stringify(summary, null, 2));
if (!summary.passed) process.exitCode = 1;

