'use strict';

const assert = require('node:assert/strict');
const { createHash } = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');

const BASELINE = '3b025df9ba5c2d5285a4cacd28382e7a3fd45a28';
const CONTRACT = 'aidlc/spaces/default/intents/260914-catchu-october-mvp/inception/contract-design';
const FILES = ['common.yaml', 'member-api.yaml', 'recipient-api.yaml', 'worker-messages.yaml'];
const METHODS = new Set(['get', 'put', 'post', 'delete', 'options', 'head', 'patch', 'trace']);
const TITLE_TARGETS = [
  ['worker-messages.yaml', 'Candidate'],
  ['common.yaml', 'Catch'],
  ['common.yaml', 'PublicCatch'],
];

if (process.argv.length !== 3) {
  console.error('Usage: node validate-contract.cjs <repository-root>');
  process.exit(2);
}
const repoRoot = fs.realpathSync(process.argv[2]);
const YAML = require(path.join(repoRoot, 'api/node_modules/yaml'));
const failures = [];
function check(name, action) {
  try {
    const details = action();
    return { passed: true, ...details };
  } catch (error) {
    const failure = { check: name, message: error.message };
    failures.push(failure);
    return { passed: false, error: failure.message };
  }
}
function read(name, baseline) {
  return baseline
    ? execFileSync('git', ['show', `${BASELINE}:${CONTRACT}/${name}`], {
      cwd: repoRoot, encoding: 'utf8', maxBuffer: 4 * 1024 * 1024,
    })
    : fs.readFileSync(path.join(repoRoot, CONTRACT, name), 'utf8');
}
function parse(text, id, file) {
  const yamlDocument = YAML.parseDocument(text, { uniqueKeys: true });
  if (yamlDocument.errors.length) {
    throw new Error(`${id}: ${yamlDocument.errors.map((error) => error.message).join('; ')}`);
  }
  const value = yamlDocument.toJS();
  assert.ok(value && typeof value === 'object' && !Array.isArray(value), `${id}: root must be a mapping`);
  return { id, file, text, yamlDocument, value };
}
function load(baseline) {
  const documents = FILES.map((file) => parse(read(file, baseline), file, file));
  const markdown = read('contract-summary.md', baseline);
  const blocks = [...markdown.matchAll(/^```yaml[ \t]*\r?\n([\s\S]*?)^```[ \t]*\r?$/gm)];
  assert.equal(blocks.length, 3, 'contract-summary.md must contain exactly three YAML blocks');
  blocks.forEach((match, index) => {
    documents.push(parse(match[1], `contract-summary.md#yaml-${index + 1}`, 'contract-summary.md'));
  });
  return { documents, byFile: new Map(documents.filter((doc) => FILES.includes(doc.file)).map((doc) => [doc.file, doc])) };
}
function pointerSegment(value) {
  return value.replaceAll('~', '~0').replaceAll('/', '~1');
}
function walk(value, pointer, visit) {
  if (value === null || typeof value !== 'object') return;
  if (Object.hasOwn(value, '$ref')) visit(value.$ref, pointer);
  for (const [key, child] of Object.entries(value)) {
    walk(child, `${pointer}/${pointerSegment(key)}`, visit);
  }
}
function resolveReference(reference, source, bundle) {
  assert.equal(typeof reference, 'string', `${source.id}: $ref must be a string`);
  const hash = reference.indexOf('#');
  const filePart = hash < 0 ? reference : reference.slice(0, hash);
  const fragment = hash < 0 ? '' : decodeURIComponent(reference.slice(hash + 1));
  let target = source;
  if (filePart) {
    assert.ok(!/^[A-Za-z][A-Za-z0-9+.-]*:/.test(filePart) && !filePart.startsWith('/'), `unsupported external reference: ${reference}`);
    const file = path.posix.normalize(path.posix.join(path.posix.dirname(source.file), decodeURIComponent(filePart)));
    target = bundle.byFile.get(file);
    assert.ok(target, `reference file not loaded: ${reference}`);
  }
  assert.ok(fragment === '' || fragment.startsWith('/'), `fragment is not a JSON Pointer: ${reference}`);
  let value = target.value;
  if (fragment) {
    for (const raw of fragment.slice(1).split('/')) {
      assert.ok(!/~(?![01])/.test(raw), `invalid JSON Pointer escape: ${reference}`);
      const key = raw.replaceAll('~1', '/').replaceAll('~0', '~');
      assert.ok(value !== null && typeof value === 'object' && Object.hasOwn(value, key), `JSON Pointer target missing: ${reference}`);
      value = value[key];
    }
  }
  return { value, document: target };
}
function referenceReport(bundle) {
  const byDocument = {};
  let count = 0;
  for (const document of bundle.documents) {
    let documentCount = 0;
    walk(document.value, '', (reference, pointer) => {
      try {
        resolveReference(reference, document, bundle);
      } catch (error) {
        throw new Error(`${document.id}${pointer}/$ref: ${error.message}`);
      }
      count += 1;
      documentCount += 1;
    });
    byDocument[document.id] = documentCount;
  }
  assert.equal(count, 203, 'total $ref occurrence count must remain 203');
  return { count, resolved: count, byDocument };
}
function dereference(value, document, bundle) {
  const visited = new Set();
  while (value && typeof value === 'object' && Object.hasOwn(value, '$ref')) {
    const key = `${document.id}\0${value.$ref}`;
    assert.ok(!visited.has(key), `cyclic operation/path reference: ${value.$ref}`);
    visited.add(key);
    ({ value, document } = resolveReference(value.$ref, document, bundle));
  }
  return { value, document };
}
function responseCodes(bundle) {
  const operations = {};
  for (const source of bundle.documents) {
    for (const [route, rawPathItem] of Object.entries(source.value.paths ?? {})) {
      const pathItem = dereference(rawPathItem, source, bundle);
      for (const [method, rawOperation] of Object.entries(pathItem.value)) {
        if (!METHODS.has(method)) continue;
        const operation = dereference(rawOperation, pathItem.document, bundle);
        const responses = dereference(operation.value.responses, operation.document, bundle).value;
        assert.ok(responses && typeof responses === 'object', `${source.id}: ${method} ${route} has no response map`);
        operations[`${source.id} ${method.toUpperCase()} ${route}`] = Object.keys(responses).sort();
      }
    }
  }
  assert.ok(Object.keys(operations).length > 0, 'no operations found');
  return operations;
}

let current;
let baseline;
const parsing = check('parse-contract-YAML', () => {
  baseline = load(true);
  current = load(false);
  return {
    baseline: baseline.documents.map((document) => document.id),
    current: current.documents.map((document) => document.id),
    currentSha256: Object.fromEntries(current.documents.map((document) => [
      document.id, createHash('sha256').update(document.text).digest('hex'),
    ])),
  };
});
const report = { repositoryRoot: repoRoot, baselineCommit: BASELINE, parsing };

if (parsing.passed) {
  report.references = check('resolve-all-references', () => ({
    baseline: referenceReport(baseline), current: referenceReport(current),
  }));
  report.responseCodes = check('operation-response-code-sets', () => {
    const expected = responseCodes(baseline);
    const actual = responseCodes(current);
    assert.deepEqual(actual, expected, 'operation response code sets changed');
    return { operationCount: Object.keys(actual).length, operations: actual };
  });
  report.titles = check('nullable-required-titles', () => {
    const checked = [];
    for (const [file, name] of TITLE_TARGETS) {
      const schema = current.byFile.get(file).value.components.schemas[name];
      const original = baseline.byFile.get(file).value.components.schemas[name];
      assert.deepEqual(schema.properties.title, { type: 'string', minLength: 1, nullable: true }, `${file} ${name}.title must match exactly`);
      assert.ok(schema.required.includes('title'), `${file} ${name}.title must remain required`);
      assert.deepEqual(schema.required, original.required, `${file} ${name}.required changed`);
      checked.push({ file, schema: name, title: schema.properties.title, required: true });
    }
    return { checked };
  });
  report.shareTitles = check('unchanged-share-titles', () => {
    const checked = [];
    for (const name of ['ShareLink', 'ShareCreate']) {
      const keys = ['components', 'schemas', name, 'properties', 'title'];
      const actualDoc = current.byFile.get('common.yaml');
      const originalDoc = baseline.byFile.get('common.yaml');
      const actual = actualDoc.yamlDocument.getIn(keys, true);
      const original = originalDoc.yamlDocument.getIn(keys, true);
      assert.ok(actual && original && actual.range && original.range, `${name}.title source node is missing`);
      assert.deepEqual(actual.toJSON(), original.toJSON(), `${name}.title schema changed`);
      assert.equal(actualDoc.text.slice(actual.range[0], actual.range[2]), originalDoc.text.slice(original.range[0], original.range[2]), `${name}.title source bytes changed`);
      checked.push({ schema: name, title: actual.toJSON(), sourceBytesUnchanged: true });
    }
    return { checked };
  });
  report.onlyAllowedYamlChanges = check('YAML-equivalence-except-three-titles', () => {
    const checked = [];
    for (const actualDoc of current.documents) {
      const originalDoc = baseline.documents.find((document) => document.id === actualDoc.id);
      assert.ok(originalDoc, `${actualDoc.id}: baseline document missing`);
      const actual = structuredClone(actualDoc.value);
      const original = structuredClone(originalDoc.value);
      for (const [file, name] of TITLE_TARGETS) {
        if (actualDoc.id !== file) continue;
        delete actual.components.schemas[name].properties.title;
        delete original.components.schemas[name].properties.title;
      }
      assert.deepEqual(actual, original, `${actualDoc.id}: YAML changed outside the three allowed title schemas`);
      checked.push(actualDoc.id);
    }
    return { checked, excluded: TITLE_TARGETS.map(([file, name]) => `${file}#/components/schemas/${name}/properties/title`) };
  });
}

report.failures = failures;
report.passed = failures.length === 0;
console.log(JSON.stringify(report, null, 2));
if (!report.passed) process.exitCode = 1;

